    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    try:
        import os
        import shutil
        import subprocess
        from threading import Thread
        from functools import wraps
        from pathlib import PurePosixPath, PureWindowsPath
        import platform
        from math import ceil

       pty = None
        if color and platform.system() in ('Linux', 'Darwin') and os.isatty(1):
            pty = PTY()

        def xargs_runner(partition):
            command = tuple(cmd) + tuple(partition)
            try:
                if pty:
                    process = subprocess.run(command,
                            stdin=pty.slave,
                            stdout=pty.slave,
                            stderr=pty.slave,
                            **kwargs,
                    )
                else:
                    process = subprocess.run(command, **kwargs)
                return process.returncode, b''
            except subprocess.CalledProcessError as exc:
                return exc.returncode, exc.output
            except FileNotFoundError:
                return 1, b'Command not found: ' + bytes(command[0], 'utf-8')

        def partition(data):
            offset = 0
            length = min(_max_length, len(data))
            while offset < len(data):
                yield data[offset:offset+length]
                offset += length

        def runner(partition):
            return xargs_runner(partition)

        with ThreadPool(target_concurrency) as pool:
            results = pool.imap_unordered(runner, partition(varargs))
            return sum(results, start=0)
    finally:
        if pty:
            pty.close()

