def xargs(cmd, varargs, color=False, target_concurrency=1, _max_length=_get_platform_max_length(), **kwargs):
    # Validate input
    if not isinstance(cmd, (tuple, list)):
        raise TypeError("cmd must be a tuple or list")
    if not all(isinstance(item, str) for item in cmd):
        raise TypeError("cmd must only contain strings")
    if not isinstance(varargs, (tuple, list)):
        raise TypeError("varargs must be a tuple or list")
    if not all(isinstance(item, str) for item in varargs):
        raise TypeError("varargs must only contain strings")
    if not isinstance(color, bool):
        raise TypeError("color must be a boolean")
    if not isinstance(target_concurrency, int):
        raise TypeError("target_concurrency must be an integer")
    if not isinstance(_max_length, int):
        raise TypeError("_max_length must be an integer")

    # Apply defaults
    kwargs = {**kwargs}
    if len(kwargs) == 0:
        kwargs["chunks"] = len(varargs)
    else:
        required_keys = {
            "chunks",
            "check_explicit",
            "check_implicit",
            "pty",
            "encoding",
            "errors",
            "preexec_fn",
            "test",
        }
        if not required_keys.issubset(kwargs.keys()):
            raise TypeError(f"Missing required keyword argument ({'|'.join(required_keys)})")

    # max_length check
    if _max_length <= 0:
        raise ValueError("_max_length must be positive")

    # cmd and varargs check
    total_length = sum(len(item) for item in cmd) + sum(len(item) for item in varargs)
    if total_length >= _max_length:
        raise ValueError(
            f"Length of cmd and varargs must be less than _max_length ({_max_length})"
        )

    # Target concurrency check
    if target_concurrency <= 0:
        raise ValueError("target_concurrency must be positive")

    # Parse command
    cmd = [item.replace("%", "%%") for item in cmd]  # Escape %
    parsed_cmd = shlex.join(cmd)

    # Partition varargs
    n_partitions = math.ceil(len(varargs) / target_concurrency)
    partitioned_varargs = [
        varargs[i * target_concurrency : (i + 1) * target_concurrency]
        for i in range(n_partitions)
    ]

    # Run xargs
    return xargs_internal(
        parsed_cmd, partitioned_varargs, color=color, _max_length=_max_length, **kwargs
    )
