def normalize_cmd(cmd: tuple[str]) -> tuple[str, ...]:
    r"""Fixes for the following issues on windows:
    - `https://bugs.python.org/issue8557`
    - Windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    new_cmd = list(cmd)
    if os.name == "nt":
        # Check if there is a credential in the path
        if "\\" in new_cmd[0]:
            # Check if the path is absolute
            if not os.path.isabs(new_cmd[0]):
                # Join the path with the current working directory
                new_cmd[0] = os.path.join(os.getcwd(), new_cmd[0])
        else:
            # Remove any extra slashes in the beginning
            while new_cmd[0][0] == "\\":
                new_cmd[0] = new_cmd[0][1:]

        # Add the current working directory to the beginning of the path
        new_cmd[0] = os.path.abspath(new_cmd[0])

        # Remove the ".exe" extension if it exists
        if new_cmd[0].endswith(".exe"):
            new_cmd[0] = new_cmd[0][:-4]

        # Check if the command path exists and is executable
        if not os.access(new_cmd[0], os.F_OK | os.R_OK | os.X_OK):
            raise FileNotFoundError(2, "The command '" + new_cmd[0] + "' does not exist or is not executable.")

        # Fix the shebang
        shebang = "/System/Library/Frameworks/Python.framework/Versions/Current/bin"
        if shebang not in new_cmd[0]:
            shebang = "/usr/lib/python"
            if shebang not in new_cmd[0]:
                raise FileNotFoundError(2, "The shebang '" + shebang + "' does not exist in the command.")

        # Replace the shebang with the current Python executable
        new_cmd[0] = os.path.join(shebang, os.environ["KRUISE_PYTHON_EXECUTABLE"])
        new_cmd[0] = new_cmd[0].split(" ")

        # Add Python to the command arguments if it's not already there
        if not any(arg.startswith("/usr/bin/env python") for arg in new_cmd):
            new_cmd.insert(1, "/usr/bin/env python")

    return tuple(new_cmd)

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    if len(cmd) == 0:
        raise ValueError("cmd cannot be empty")
    if any(not isinstance(elem, str) for elem in cmd):
        raise ValueError("all elements of cmd must be str")
    if not cmd[0].startswith('python'):
        return cmd
    new_cmd = []
    for elem in cmd:
        if elem.endswith('&'):
            new_cmd.append('nohup')
            new_cmd.append(elem[:-1])
        elif elem.startswith('/'):
            new_cmd.append('python')
            new_cmd.append(elem)
        else:
            new_cmd.append(elem)
    return new_cmd

