def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:`generate_default_observer_schema_list`, this function is
    called recursively to generate part of a default `observer_schema` from part of a
    Kubernetes resource, defined respectively by `manifest_dict` or `manifest_list`.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from `manifest_dict` and replaces all
    non-list and non-dict values by `None`.

    In case of `first_level` dictionary (i.e. complete `observer_schema` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """

    def _generate_default_dict(manifest_dict):
        new_dict = {}
        for key, value in manifest_dict.items():
            if isinstance(value, dict):
                new_dict[key] = _generate_default_dict(value)
            elif isinstance(value, list):
                new_dict[key] = []
                for element in value:
                    if isinstance(element, dict):
                        new_dict[key].append(_generate_default_dict(element))
                    else:
                        new_dict[key].append(None)
            else:
                new_dict[key] = None
        return new_dict

    if first_level:
        # Copy identifying fields from manifest file
        new_dict = {
            "apiVersion": manifest_dict["apiVersion"],
            "kind": manifest_dict["kind"],
            "metadata": {
                "name": manifest_dict["metadata"]["name"]
            }
        }
        return new_dict
    else:
        return _generate_default_dict(manifest_dict)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource.

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    Raises:
        ValueError: If the input manifest_dict is empty or not a valid Kubernetes resource manifest.
        KeyError: If a required key is missing in the manifest_dict.
    """
    if not manifest_dict:
        raise ValueError("Input manifest_dict is empty.")
    try:
        _ = manifest_dict["apiVersion"]
        _ = manifest_dict["kind"]
        _ = manifest_dict["metadata"]["name"]
    except KeyError:
        raise KeyError(
            "At least one of the required keys 'apiVersion', 'kind', or 'metadata.name' is missing in the input manifest_dict."
        )
    observer_schema = {}
    for key, val in manifest_dict.items():
        if isinstance(val, dict):
            observer_schema[key] = generate_default_observer_schema_dict(
                val, first_level=False
            )
        elif isinstance(val, list):
            observer_schema[key] = generate_default_observer_schema_list(
                val, first_level=False
            )
        else:
            observer_schema[key] = None
    if first_level:
        observer_schema["metadata"] = manifest_dict["metadata"]
    return observer_schema

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    Raises:
        TypeError: if last_applied_manifest, observer_schema or response is not a list
        ValueError: if last_applied_manifest or observer_schema is not a list of dicts
    """
    if not isinstance(last_applied_manifest, list):
        raise TypeError("last_applied_manifest must be a list")
    if not isinstance(observer_schema, list):
        raise TypeError("observer_schema must be a list")
    if not isinstance(response, list):
        raise TypeError("response must be a list")

    for i, item in enumerate(observer_schema):
        if not isinstance(item, dict):
            raise ValueError("observer_schema must be a list of dicts")
        if not isinstance(response[i], dict):
            raise ValueError("response must be a list of dicts")

        for key, value in item.items():
            if key not in last_applied_manifest:
                last_applied_manifest[key] = value
            elif isinstance(value, list):
                update_last_applied_manifest_list_from_resp(last_applied_manifest[key], value, response[i][key])
            elif isinstance(value, dict):
                update_last_applied_manifest_dict_from_resp(last_applied_manifest[key], value, response[i][key])
            else:
                last_applied_manifest[key] = value

    return last_applied_manifest

