def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # First, gather all the digests that are needed by the manifest.
    needed_digests = set()
    for manifest_file in manifest_files:
        needed_digests.update(manifest_file.digests)
    # Next, make sure that all the digests that are used are in the set of needed digests.
    for digest_used in digests_used:
        if digest_used not in needed_digests:
            raise ValueError("Digest {} is used but not present in manifest.".format(digest_used))
    # Finally, make sure that all the needed digests are used.
    for needed_digest in needed_digests:
        if needed_digest not in digests_used:
            raise ValueError("Digest {} is needed but not used.".format(needed_digest))

