def validate_as_prior_version(self, prior: InventoryValidator) -> None:
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        if not isinstance(prior, InventoryValidator):
            raise TypeError("Prior version must be an instance of InventoryValidator, got {}".format(type(prior)))

        if prior.inventory.id != self.inventory.id:
            raise ValueError("Prior version is not for the same inventory, got {}".format(prior.inventory.id))

        if prior.inventory.version >= self.inventory.version:
            raise ValueError("Prior version must have a lower version number than the current version, got {}".format(prior.inventory.version))

        # Check that all elements in the current inventory are also in the prior inventory
        for elem in self.inventory.get_elements():
            if not prior.inventory.has_element(elem):
                raise ValueError("Element '{}' missing in prior version".format(elem.id))

            prior_elem = prior.inventory.get_element(elem.id)

            # Check that all attributes in the current element are also in the prior element
            for name, value in elem.get_attributes().items():
                if not prior_elem.has_attribute(name):
                    raise ValueError("Attribute '{}' missing in prior version of element '{}'".format(name, elem.id))

                prior_value = prior_elem.get_attribute(name)
                if prior_value != value:
                    raise ValueError("Attribute '{}' has a different value in prior version of element '{}': {} vs {}".format(name, elem.id, prior_value, value))

        # Check that all links in the current inventory are also in the prior inventory
        for link in self.inventory.get_links():
            if not prior.inventory.has_link(link.id):
                raise ValueError("Link '{}' missing in prior version".format(link.id))

            prior_link = prior.inventory.get_link(link.id)

            # Check that all attributes in the current link are also in the prior link
            for name, value in link.get_attributes().items():
                if not prior_link.has_attribute(name):
                    raise ValueError("Attribute '{}' missing in prior version of link '{}'".format(name, link.id))

                prior_value = prior_link.get_attribute(name)
                if prior_value != value:
                    raise ValueError("Attribute '{}' has a different value in prior version of link '{}': {} vs {}".format(name, link.id, prior_value, value))

            # Check that the current link ends are the same as in the prior version
            if link.end1.id != prior_link.end1.id or link.end2.id != prior_link.end2.id:
                raise ValueError("Link '{}' has a different end in the prior version".format(link.id))

        # Check that all attributes in the current inventory are also in the prior inventory
        for attr in self.inventory.get_attributes():
            if not prior.inventory.has_attribute(attr):
                raise ValueError("Attribute '{}' missing in prior version".format(attr))

            prior_attr = prior.inventory.get_attribute(attr)
            if prior_attr != self.inventory.get_attribute(attr):
                raise ValueError("Attribute '{}' has a different value in prior version: {} vs {}".format(attr, prior_attr, self.inventory.get_attribute(attr)))

