    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """

    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    for k, v in fixity.items():
        if k not in manifest_files:
            raise ValueError(f"File {k} is not listed in the manifest")

        if not isinstance(v, str):
            raise ValueError(f"Fixity value for file {k} must be a string")

        try:
            algorithm, value = v.split(":")
        except ValueError:
            raise ValueError(f"Invalid fixity value for file {k}: must be of the form 'algorithm:hash'")

        if algorithm not in hashlib.algorithms_guaranteed:
            raise ValueError(f"Unknown fixity algorithm {algorithm} for file {k}")

        if not re.match(r"^[a-f0-9]+$", value):
            raise ValueError(f"Invalid hash value {value} for file {k}: must be a hexadecimal string")

