    try:
        int(version)
    except ValueError:
        raise ValueError("Version must be a string representing an integer")

    version_parts = version.split(".")
    if len(version_parts) != 3:
        raise ValueError("Version must have 3 parts separated by dots")

    major = int(version_parts[0])
