        inventory_df = pd.read_excel(inventory_file)
        expected_columns = ['filename', 'identifier', 'digest', 'allowed_actions']
        if not all(col in inventory_df.keys() for col in expected_columns):
            raise Exception(f"Inventory file for version {version} does not contain all the expected columns")

        # Check that the digests match the ones in the root inventory, if they don't add them to a list to check later
        for index, row in inventory_df.iterrows():
            if row['digest'] != self.root_digests.get(row['identifier'], None):
                self.different_digests[row['identifier']] = [self.root_digests[row['identifier']], row['digest']]

    # Check that the different digests are not due to changed elements
    for identifier, digests in self.different_digests.items():
        id_path = identifier.split('.')
        if self.root_ids.get(id_path[0], None):
