def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not commands:
        raise ValueError("Cannot call an empty command")
    if not isinstance(commands, (str, list, tuple)):
        raise TypeError("Commands must be a string, list, or tuple")
    if args and not isinstance(args, (str, list, tuple)):
        raise TypeError("Args must be a string, list, or tuple")
    if cwd and not isinstance(cwd, str):
        raise TypeError("CWD must be a string")
    if env and not isinstance(env, dict):
        raise TypeError("Env must be a dictionary")

    if isinstance(commands, str):
        commands = [commands]
    if isinstance(args, str):
        args = [args]

    for command in commands:
        if not isinstance(command, str):
            raise TypeError("Commands must be strings")
        command = command.strip()
        if not command:
            raise ValueError("Cannot call an empty command")
        if verbose:
            print("Calling command:", command)
        try:
            subprocess.check_call(command, shell=True, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)
        except subprocess.CalledProcessError as exc:
            if hide_stderr:
                print("Command failed:", exc.returncode)
            else:
                raise
    return True

def run_command(self, commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    if isinstance(commands, str):
        commands = [commands]

    if isinstance(args, (list, tuple)):
        args = [' '.join(args)]

    if not isinstance(commands, (list, tuple)):
        raise ValueError('commands must be a str or a list of str')

    if not isinstance(args, (list, tuple)):
        raise ValueError('args must be a str or a list of str')

    if cwd is not None and not isinstance(cwd, str):
        raise ValueError('cwd must be a str or None')

    if env is not None and not isinstance(env, dict):
        raise ValueError('env must be a dict or None')

    process = subprocess.Popen(commands + args,
                            stdout=subprocess.PIPE,
                            stderr=subprocess.PIPE,
                            cwd=cwd,
                            env=env)

    stdout, stderr = process.communicate()

    if process.returncode != 0:
        raise Exception('Command returned non-zero exit code %d: %s' % (process.returncode, ' '.join(commands + args)))

    if hide_stderr:
        stderr = None

    return CompletedProcess(process.args, process.returncode, stdout, stderr)

