    x = []
    y = []
    for bin_ in hist:
        x.append(coordinates_func(bin_))
        if make_value is None:
            y.append(bin_.value)
        else:
            y.append(make_value(bin_))

    graph = Graph(x, y, scale=scale, field_names=field_names)
    return graph

