def verifyObject(iface, candidate, tentative=False):
    # Check that the candidate claims to provide the interface
    if not tentative:
        if not iface.providedBy(candidate):
            raise Invalid("Candidate does not provide the given interface")

    # Check that the candidate defines all the necessary methods
    for m in iface.getMethods():
        if not hasattr(candidate, m):
            raise Invalid("Candidate does not define required method: {}".format(m))

        # Check that the methods have the correct signature
        public_attributes = getattr(candidate, m).__self__.__class__.__dict__
        if not set(public_attributes).issuperset(iface.getArguments()):
            raise Invalid("Candidate's method {} has a signature that is not a superset of the required arguments".format(m))

    # Check that the candidate defines all the necessary attributes
    for a in iface.getAttributes():
        if not hasattr(candidate, a):
            raise Invalid("Candidate does not define required attribute: {}".format(a))

    return True
