def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    # Split the text into words and links
    words = text.split()
    links = []

    # Iterate over the words and look for links
    for word in words:
        if word.startswith('http'):
            links.append(word)

    # Remove the links from the text
    for link in links:
        words.remove(link)

    # Add the links to the text as HTML links
    for link in links:
        words.append(f'<a href="{link}">{link}</a>')

    return ' '.join(words)

