def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    type_instance = None

    if type_name == "choice":
        type_instance = spec_option
    elif type_name == "list":
        type_instance = spec_option.split(",")
    elif type_name == "dict":
        type_instance = spec_option.split("::")
    elif type_name == "date":
        type_instance = datetime.strptime(spec_option, "%Y-%m-%d")
    elif type_name == "bool":
        type_instance = spec_option.lower() == "true"
    else:
        raise ValueError(f"Invalid complex type {type_name} for option {option_name} in subcommand {subcommand}")

    return type_instance

def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    try:
        complex_type = getattr(self, type_name)
    except AttributeError:
        raise ValueError(f"Invalid complex type '{type_name}'")

    if not issubclass(complex_type, ComplexType):
        raise ValueError(f"'{type_name}' is not a subclass of ComplexType")

    return complex_type(subcommand, option_name, spec_option)

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if isinstance(arg, ControlArg):
            control_args[arg.name] = arg.value
        elif isinstance(arg, NestedArg):
            nested_args[arg.name] = arg.value
        elif isinstance(arg, CustomArg):
            custom_args[arg.name] = arg.value
        else:
            raise ValueError(f"Invalid argument type: {arg}")

    # Remove duplicate args
    for arg in control_args.keys():
        if arg in nested_args or arg in custom_args:
            raise ValueError(f"Duplicate argument: {arg}")

    return control_args, nested_args, custom_args

