def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active workspace.
    :param ir_plugin: An InfraredPlugin object of the current plugin.
    :param playbook_path: The playbook to invoke.
    :param verbose: Ansible verbosity level.
    :param extra_vars: A dict of 'extra-vars' to pass to Ansible.
    :param ansible_args: A dict of 'ansible-playbook' arguments to pass to Ansible.
    """

    ansible_path = ir_workspace.injector.get('ansible_path')
    if ansible_path:
        args = [ansible_path, 'ansible-playbook', playbook_path]
    else:
        args = ['ansible-playbook', playbook_path]

    if verbose is not None:
        args.extend(['-v', str(verbose)])

    if extra_vars:
        args.extend(['-e', str(extra_vars)])

    if ansible_args:
        args.extend(str(arg) for arg in ansible_args)

    p = subprocess.Popen(args, cwd=ir_workspace.root_path, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    out, err = p.communicate()
    if p.returncode != 0:
        raise subprocess.CalledProcessError(p.returncode, " ".join(args))

    return out.decode('utf-8').strip(), err.decode('utf-8').strip()

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active
    workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: the playbook to invoke
    :param verbose: Ansible verbosity level
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down
    directly to Ansible.
    """
    # validate the input parameters
    if not ir_workspace or not isinstance(ir_workspace, Workspace):
        raise InvalidWorkspaceError("Invalid ir_workspace parameter. Must be a Workspace object")
    if not ir_plugin or not isinstance(ir_plugin, Plugin):
        raise InvalidPluginError("Invalid ir_plugin parameter. Must be a Plugin object")
    if not playbook_path or not os.path.exists(playbook_path):
        raise InvalidPlaybookPathError("Invalid playbook_path parameter. Must be a valid path to a playbook file")
    if verbose and not isinstance(verbose, int):
        raise InvalidVerbosityLevelError("Invalid verbose parameter. Must be an integer between 0 and 4")
    if extra_vars and not isinstance(extra_vars, dict):
        raise InvalidExtraVarsError("Invalid extra_vars parameter. Must be a valid dict object containing extra-vars for Ansible")
    if ansible_args and not isinstance(ansible_args, dict):
        raise InvalidAnsibleArgsError("Invalid ansible_args parameter. Must be a valid dict object containing additional arguments for the ansible-playbook command")
    # construct the ansible-playbook command
    cmd = ['ansible-playbook', playbook_path]
    if verbose:
        cmd.append('-' + 'v' * verbose)
    if extra_vars:
        for k, v in extra_vars.items():
            cmd.append('-e')
            cmd.append(str(k) + '=' + str(v))
    if ansible_args:
        cmd.extend(ansible_args)
    # add additional arguments for the Infrared extensibility framework
    cmd.extend(['--ir-workspace', str(ir_workspace.id)])
    cmd.extend(['--ir-plugin', str(ir_plugin.id)])
    # execute the ansible-playbook command
    try:
        return subprocess.check_output(cmd, universal_newlines=True)
    except subprocess.CalledProcessError as e:
        raise AnsiblePlaybookError("Failed to execute ansible-playbook command. Exit code: {}. Output: {}".format(e.returncode, e.output))

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    playbook_path = ir_plugin.playbook_path
    if not playbook_path:
        return None
    playbook_path = join(ir_workspace.root, playbook_path)
    if not exists(playbook_path):
        return None
    if not isinstance(vars_dict, dict):
        vars_dict = {}
    cli_args = cli_args or []
    cli_args.extend(['-i', 'localhost', playbook_path])

    env = dict(os.environ)
    workspace_path = ir_workspace.root
    env['WORKSPACE_PATH'] = workspace_path
    if ir_workspace.password:
        env['WORKSPACE_PASSWORD'] = ir_workspace.password
    if ir_workspace.sudo_password:
        env['ANSIBLE_SUDO_PASSWORD'] = ir_workspace.sudo_password
    env['ANSIBLE_VAULT_PASSWORD'] = ir_workspace.vault_password
    env['ANSIBLE_VERBOSITY'] = str(ir_workspace.verbosity)

    extra_vars = json.dumps(vars_dict)
    process = Popen(cli_args, cwd=workspace_path, env=env, stdout=PIPE, stderr=PIPE, stdin=PIPE, universal_newlines=True)
    try:
        outs, errs = process.communicate(extra_vars, timeout=ir_plugin.timeout)
        results = {
            'stdout': outs,
            'stderr': errs,
            'returncode': process.returncode,
        }
        return results
    except CalledProcessError as e:
        return {
            'stdout': '',
            'stderr': e.output,
            'returncode': e.returncode,
        }
    except TimeoutExpired as e:
        process.kill()
        return {
            'stdout': '',
            'stderr': 'Timed out after %s seconds' % str(ir_plugin.timeout),
            'returncode': 1,
        }

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if not isinstance(parser_name, str):
        raise TypeError("parser_name should be a string")
    if not isinstance(values_dict, dict):
        raise TypeError("values_dict should be a dict")

    for arg_name, value in values_dict.items():
        # Get the argument type
        arg_type = self._arg_types.get(arg_name)
        if arg_type is None:
            continue

        # Convert the value to the correct type
        if issubclass(arg_type, bool):
            values_dict[arg_name] = bool(value)
        elif issubclass(arg_type, int):
            try:
                values_dict[arg_name] = int(value)
            except ValueError:
                raise ValueError(f"Invalid value for {arg_name}: {value}")
        elif issubclass(arg_type, float):
            try:
                values_dict[arg_name] = float(value)
            except ValueError:
                raise ValueError(f"Invalid value for {arg_name}: {value}")
        elif issubclass(arg_type, enum.Enum):
            try:
                values_dict[arg_name] = arg_type[value]
            except KeyError:
                raise ValueError(f"Invalid value for {arg_name}: {value}")
        else:
            raise ValueError(f"Unsupported argument type: {arg_type}")

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    for each_arg in values_dict.keys():
        convert_arg = getattr(self.get_command_parser(parser_name), each_arg)
        if convert_arg.type != str:
            if convert_arg.type == bool:
                values_dict[each_arg] = str_to_bool(values_dict[each_arg])
            elif convert_arg.type == list:
                values_dict[each_arg] = values_dict[each_arg].split(',')
            else:
                values_dict[each_arg] = convert_arg.type(values_dict[each_arg])
