def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    try:
        plugin_spec = None
        plugin_spec = _load_plugin_spec(plugin_dir)
        _validate_plugin_spec(plugin_spec)
        return _flatten_dict(plugin_spec)
    except Exception as e:
        raise ValueError("Error getting plugin spec flatten dict: " + str(e))

def _load_plugin_spec(plugin_dir):
    spec_path = os.path.join(plugin_dir, "plugin_spec.json")
    if not os.path.exists(spec_path):
        return {}
    with open(spec_path, "r") as f:
        plugin_spec = json.load(f)
    return plugin_spec

def _validate_plugin_spec(plugin_spec):
    required_keys = ["name", "version", "entrypoint"]
    for key in required_keys:
        if key not in plugin_spec:
            raise ValueError("Invalid plugin spec, missing key: " + key)
    if not isinstance(plugin_spec["version"], str) or len(plugin_spec["version"]) == 0:
        raise ValueError("Invalid plugin spec, version must be a non-empty string")
    if not isinstance(plugin_spec["entrypoint"], str) or len(plugin_spec["entrypoint"]) == 0:
        raise ValueError("Invalid plugin spec, entrypoint must be a non-empty string")
    if "dependencies" in plugin_spec and not isinstance(plugin_spec["dependencies"], list):
        raise ValueError("Invalid plugin spec, dependencies must be a list")

def _flatten_dict(obj):
    flat_dict = {}
    for key, value in obj.items():
        flat_dict[key] = value
        if isinstance(value, dict):
            flat_dict.update(_flatten_dict(value))
    return flat_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    Args:
        plugin_dir (str): A path to the plugin's dir

    Returns:
        dict: A flatten dictionary contains the plugin's properties
    """
    if not os.path.isdir(plugin_dir):
        raise ValueError("Invalid plugin directory: %s" % plugin_dir)

    plugin_spec = {}
    try:
        with open(os.path.join(plugin_dir, "plugin_spec.json"), "r") as f:
            plugin_spec = json.load(f)

        # Flatten the plugin spec dict
        flatten_dict = {}
        for key, value in plugin_spec.items():
            if isinstance(value, dict):
                for sub_key, sub_value in value.items():
                    flatten_dict["%s.%s" % (key, sub_key)] = sub_value
            else:
                flatten_dict[key] = value
        return flatten_dict
    except Exception as e:
        raise ValueError("Invalid plugin spec: %s" % e)

